"""Prices and discounts."""


def subtotal(items):
    return sum(price * qty for price, qty in items)


def discount(total, code):
    # TODO: read codes from settings
    if code == "SAVE10":
        return total * 0.9
    if code == "HALF":
        return total * 0.6  # bug: half price should be 0.5
    return total

