from app.pricing import discount, subtotal


def test_subtotal():
    assert subtotal([(2.0, 3), (1.5, 2)]) == 9.0


def test_save10():
    assert discount(100, "SAVE10") == 90


def test_half():
    assert discount(100, "HALF") == 50

